<template><view class="module"><MobileHeader :title="title" back-icon-name="chevron-left" :action-text="app==='voice'?'手机宠':''" @action="pet"/><view v-if="!session.identity" class="guest"><AppIcon :name="app==='voice'?'microphone':'ai'" :size="44" color="#b2bdd7"/><text>{{title}}</text><text class="muted">登录后连接你的助手</text><button @tap="login">账号登录</button></view><view v-else-if="error" class="guest"><text>{{error}}</text><button @tap="load">重试</button></view>
<!-- #ifdef H5 --><iframe v-if="url&&session.identity" :src="url" :title="title" allow="microphone; autoplay" class="frame" referrerpolicy="no-referrer"></iframe><!-- #endif -->
<!-- #ifdef APP-PLUS --><web-view v-if="url&&session.identity" :src="url" :webview-styles="{top:webviewTop}"/><!-- #endif -->
</view></template><script setup lang="ts">import {ref,watch} from 'vue';import {onLoad,onUnload} from '@dcloudio/uni-app';import MobileHeader from '@/components/MobileHeader.vue';import AppIcon from '@/components/AppIcon.vue';import {applicationUrl,session,openLogin} from '@/platform';const webviewTop=((uni.getSystemInfoSync().statusBarHeight||0)+52)+'px',url=ref(''),title=ref('应用'),error=ref(''),app=ref('');let generation=0;async function load(){const rev=++generation;url.value='';error.value='';if(!session.identity||!app.value)return;try{const next=await applicationUrl(app.value as any);if(rev===generation)url.value=next;}catch{if(rev===generation)error.value='应用服务暂时未连接';}}function login(){openLogin('/pages/module/index?app='+app.value);}function pet(){uni.navigateTo({url:'/pages/pet/index'});}onUnload(()=>{generation++;url.value='';});watch(()=>session.identity,load);onLoad(q=>{if(!['chat','work','voice'].includes(q?.app)){error.value='应用不存在';return;}app.value=q!.app;title.value=({chat:'聊天',work:'工作',voice:'语音'})[app.value as 'chat'|'work'|'voice'];void load();});</script><style scoped>.module{box-sizing:border-box;height:100dvh;padding:12px 16px;display:flex;flex-direction:column}.frame{width:100%;flex:1;min-height:0;border:0}.guest{max-width:400px;margin:100px auto 0;display:flex;flex-direction:column;align-items:center;gap:18px}.guest>text{font-size:18px}.guest>.muted{font-size:13px;color:#8b95a6}.guest button{margin-top:12px;background:#294fdb;color:#fff;border-radius:12px;font-size:14px;padding:0 35px}</style>
